<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>e-CMR Verification</title><style>body{font-family:Arial;background:#f1f5f9;color:#0f172a;margin:0;padding:24px}.card{max-width:760px;margin:auto;background:#fff;border-radius:18px;padding:28px;box-shadow:0 10px 30px #0f172a18}.ok{color:#047857}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.box{border:1px solid #e2e8f0;border-radius:12px;padding:14px}.hash{word-break:break-all;font-family:monospace;font-size:12px}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><main class="card">
